// Exit Intent Popup - Only for Contact Page console.log('EXIT-INTENT.JS FILE LOADED'); document.addEventListener('DOMContentLoaded', () => { initExitIntentPopup(); }); function initExitIntentPopup() { console.log('Exit intent popup initializing...'); // Configuration constants const EXIT_INTENT_CONFIG = { MOUSE_VELOCITY_THRESHOLD: 50, // Pixels per mousemove event MOUSE_TOP_POSITION_PX: 100, // Top area of viewport to trigger MOBILE_SWIPE_THRESHOLD_PX: 100, // Swipe down distance to trigger SCROLL_TOP_THRESHOLD_PX: 50, // Consider "at top" if scrollTop < this AUTO_SHOW_DELAY_MS: 20000 // Show after 20 seconds (capture contractors before they leave) }; const exitPopup = document.getElementById('exitPopup'); console.log('exitPopup element:', exitPopup); if (!exitPopup) { console.log('exitPopup not found, exiting'); return; } const closeBtn = exitPopup.querySelector('.exit-popup-close'); const dismissBtn = exitPopup.querySelector('.exit-popup-dismiss'); const ctaBtn = exitPopup.querySelector('.exit-popup-cta'); let popupShown = false; let formSubmitted = false; // Check if popup was previously dismissed (clears on browser close) const popupDismissed = sessionStorage.getItem('exitPopupDismissed'); // DEBUG: To test the popup, open browser console and run: // sessionStorage.removeItem('exitPopupDismissed') // Then refresh the page and move mouse to top const contactForm = document.querySelector('.contact-form'); if (contactForm) { contactForm.addEventListener('submit', () => { formSubmitted = true; sessionStorage.setItem('exitPopupDismissed', 'true'); }); } function showPopup(manual = false) { console.log('showPopup called, manual:', manual, 'popupShown:', popupShown, 'popupDismissed:', popupDismissed); // If manually triggered (skip button), always show if (!manual && (popupShown || popupDismissed || formSubmitted)) return; popupShown = true; exitPopup.classList.add('visible'); document.body.style.overflow = 'hidden'; console.log('Popup should now be visible, classes:', exitPopup.className); } function hidePopup() { exitPopup.classList.remove('visible'); document.body.style.overflow = ''; sessionStorage.setItem('exitPopupDismissed', 'true'); } // Manual trigger - Skip form button const skipFormBtn = document.getElementById('skipFormBtn'); console.log('skipFormBtn element:', skipFormBtn); if (skipFormBtn) { skipFormBtn.addEventListener('click', () => { console.log('Skip button clicked!'); showPopup(true); // Manual trigger, bypass checks }); } // Primary exit intent detection - when mouse moves toward top of viewport document.addEventListener('mouseout', (e) => { // Detect mouse leaving toward top of page (toward browser controls) // Check if mouse is at/near top AND leaving the page const isNearTop = e.clientY <= 10; const isLeavingPage = !e.relatedTarget || e.relatedTarget.nodeName === 'HTML'; if (isNearTop && isLeavingPage) { showPopup(); } }); // Backup detection: fast upward movement to top let lastY = 0; document.addEventListener('mousemove', (e) => { const velocity = lastY - e.clientY; lastY = e.clientY; // Trigger if mouse moves up quickly and is near top of viewport if (velocity > EXIT_INTENT_CONFIG.MOUSE_VELOCITY_THRESHOLD && e.clientY < EXIT_INTENT_CONFIG.MOUSE_TOP_POSITION_PX) { showPopup(); } }); let touchStartY = 0; document.addEventListener('touchstart', (e) => { touchStartY = e.touches[0].clientY; }, { passive: true }); document.addEventListener('touchend', (e) => { const touchEndY = e.changedTouches[0].clientY; const scrollTop = window.pageYOffset || document.documentElement.scrollTop; // Trigger if at top of page and swiping down (pull-to-refresh gesture) if (scrollTop < EXIT_INTENT_CONFIG.SCROLL_TOP_THRESHOLD_PX && touchEndY - touchStartY > EXIT_INTENT_CONFIG.MOBILE_SWIPE_THRESHOLD_PX) { showPopup(); } }, { passive: true }); // Time-based fallback - show after user has been on page for a while setTimeout(() => { showPopup(); }, EXIT_INTENT_CONFIG.AUTO_SHOW_DELAY_MS); if (closeBtn) { closeBtn.addEventListener('click', hidePopup); } if (dismissBtn) { dismissBtn.addEventListener('click', hidePopup); } exitPopup.addEventListener('click', (e) => { if (e.target === exitPopup) { hidePopup(); } }); document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && exitPopup.classList.contains('visible')) { hidePopup(); } }); if (ctaBtn) { ctaBtn.addEventListener('click', () => { sessionStorage.setItem('exitPopupDismissed', 'true'); }); } } 